const fs = require("fs");
const path = require("path");
const table = JSON.parse(fs.readFileSync(path.join(__dirname, "src", "tax-table.src.json"), "utf8"));
fs.mkdirSync(path.join(__dirname, "src", "generated"), { recursive: true });
fs.writeFileSync(
  path.join(__dirname, "src", "generated", "tax-table.js"),
  "// GENERATED by build.js from src/tax-table.src.json. Do not edit.\nmodule.exports = " + JSON.stringify(table, null, 2) + ";\n"
);
